using System.Collections.Generic;
using System.Text.Json.Serialization;

namespace KAONOMI.Chat.Models;

/// <summary>
/// Request of <c>POST /image/generate</c> (<c>ImageGenerationRequest</c> on the server side): images generated by Fooocus
/// from a prompt. The fields left null take the defaults of Fooocus.
/// </summary>
public sealed class ImageGenerationRequest
{
    [JsonPropertyName("prompt")]
    public string Prompt { get; set; } = string.Empty;

    [JsonPropertyName("negativePrompt")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? NegativePrompt { get; set; }

    /// <summary>Fooocus styles; null: the default ones.</summary>
    [JsonPropertyName("styles")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public List<string>? Styles { get; set; }

    /// <summary>Quality, Speed, Extreme Speed, Lightning or Hyper-SD.</summary>
    [JsonPropertyName("performance")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? Performance { get; set; }

    /// <summary>width*height, e.g. 1152*896.</summary>
    [JsonPropertyName("aspectRatio")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? AspectRatio { get; set; }

    [JsonPropertyName("imageNumber")]
    public int ImageNumber { get; set; } = 1;

    /// <summary>-1: a random seed.</summary>
    [JsonPropertyName("seed")]
    public long Seed { get; set; } = -1;

    [JsonPropertyName("outputFormat")]
    public string OutputFormat { get; set; } = "png";

    /// <summary>Checkpoint file; null: the default model.</summary>
    [JsonPropertyName("baseModel")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? BaseModel { get; set; }

    /// <summary>The images come back in base 64 (the chat saves them in its own folder).</summary>
    [JsonPropertyName("includeBase64")]
    public bool IncludeBase64 { get; set; } = true;
}

/// <summary>Answer of <c>POST /image/generate</c>: the images, the seed, the model and the time taken, or an error.</summary>
public sealed class ImageGenerationResult
{
    [JsonPropertyName("images")]
    public List<GeneratedImage> Images { get; set; } = [];

    [JsonPropertyName("seed")]
    public long Seed { get; set; }

    [JsonPropertyName("seconds")]
    public double Seconds { get; set; }

    [JsonPropertyName("model")]
    public string? Model { get; set; }

    [JsonPropertyName("error")]
    public string? Error { get; set; }
}

/// <summary>A generated image: its file on the machine of Fooocus and its data in base 64.</summary>
public sealed class GeneratedImage
{
    [JsonPropertyName("path")]
    public string Path { get; set; } = string.Empty;

    [JsonPropertyName("base64")]
    public string? Base64 { get; set; }
}

/// <summary>Answer of <c>GET /image/options</c>: what a generation accepts and the defaults of Fooocus.</summary>
public sealed class ImageOptions
{
    [JsonPropertyName("styles")]
    public List<string> Styles { get; set; } = [];

    [JsonPropertyName("performances")]
    public List<string> Performances { get; set; } = [];

    [JsonPropertyName("aspect_ratios")]
    public List<string> AspectRatios { get; set; } = [];

    [JsonPropertyName("models")]
    public List<string> Models { get; set; } = [];

    [JsonPropertyName("default_styles")]
    public List<string> DefaultStyles { get; set; } = [];

    [JsonPropertyName("default_performance")]
    public string? DefaultPerformance { get; set; }

    [JsonPropertyName("default_aspect_ratio")]
    public string? DefaultAspectRatio { get; set; }

    [JsonPropertyName("default_model")]
    public string? DefaultModel { get; set; }
}

/// <summary>What was asked for an image saved by <c>/fooocus</c> (written next to it as name.json).</summary>
public sealed class FooocusImageInfo
{
    [JsonPropertyName("prompt")]
    public string Prompt { get; set; } = string.Empty;

    [JsonPropertyName("negativePrompt")]
    public string? NegativePrompt { get; set; }

    [JsonPropertyName("styles")]
    public List<string> Styles { get; set; } = [];

    [JsonPropertyName("performance")]
    public string? Performance { get; set; }

    [JsonPropertyName("aspectRatio")]
    public string? AspectRatio { get; set; }

    [JsonPropertyName("seed")]
    public long Seed { get; set; }

    [JsonPropertyName("model")]
    public string? Model { get; set; }

    [JsonPropertyName("seconds")]
    public double Seconds { get; set; }

    [JsonPropertyName("date")]
    public System.DateTimeOffset Date { get; set; }
}
